// Adds each preset's trim to its master gain so factory presets play back at matched loudness.
inline void applyLoudnessTrims(std::vector<Preset>& bank) {
    const auto& t = loudnessTrims();
    for (auto& p : bank) {
        const auto it = t.find(p.name);
        if (it != t.end()) {
            float& g = p.v[size_t(gp(G_Gain))];
            g = std::max(-36.f, std::min(18.f, g + it->second));
        }
    }
}

